1	import { create } from "zustand";
2	import { persist, createJSONStorage } from "zustand/middleware";
3	import type { Store } from "types/store";
4	
5	// Create the store with minimal state
6	const useStore = create<Store>()(
7	  persist(
8	    (set) => ({
9	      // Initial UI state
10	      openModal: false,
11	      hydrated: false,
12	
13	      // Initial user location
14	      userLocation: null,
15	
16	      // Actions
17	      setState: (key, value) => {
18	        set((state) => {
19	          // Only update the specific property to avoid unnecessary re-renders
20	          if (state[key] === value) return state; // Skip if value hasn't changed
21	          return { ...state, [key]: value };
22	        });
23	      },
24	
25	      setHydrated: () => {
26	        set((state) => ({ ...state, hydrated: true }));
27	      },
28	    }),
29	    {
30	      name: "events-ui",
31	      storage: createJSONStorage(() => localStorage),
32	      partialize: (state) => ({
33	        // Only persist UI state that should survive browser restarts
34	        hydrated: state.hydrated,
35	      }),
36	    }
37	  )
38	);
39	
40	export default useStore;
