5	/**
6	 * Transform regions data to flat Option[] for searchable select
7	 * Reuses existing Option interface and sanitize function for URL consistency
8	 */
9	export function transformRegionsToOptions(
10	  regions: RegionsGroupedByCitiesResponseDTO[]
11	): Option[] {
12	  const options: Option[] = [];
13	
14	  regions.forEach((region) => {
15	    // Add region itself as option using API-provided slug (fall back to slugified name)
16	    options.push({
17	      value: region.slug ?? sanitize(region.name),
18	      label: region.name,
19	    });
20	
21	    // Add all cities in region (cities already have URL-friendly values)
22	    region.cities.forEach((city) => {
23	      options.push({
24	        value: city.value,
25	        label: city.label,
26	      });
27	    });
28	  });
29	
30	  return options;
31	}
