46	/**
47	 * Debounce function for search input
48	 */
49	export function debounce<T extends (..._args: unknown[]) => void>(
50	  func: T,
51	  wait: number
52	): (..._args: Parameters<T>) => void {
53	  let timeout: ReturnType<typeof setTimeout> | null = null;
54	
55	  return function (...args: Parameters<T>) {
56	    if (timeout) clearTimeout(timeout);
57	    timeout = setTimeout(() => func(...args), wait);
58	  };
59	}
