1	"use client";
2	import { useState, useCallback } from "react";
3	import { useTranslations } from "next-intl";
4	import { Option } from "types/common";
5	import { UseGeolocationReturn } from "types/props";
6	import { findNearestCity } from "../../components/ui/locationDiscoveryWidget/utils";
7	import { RegionsGroupedByCitiesResponseDTO } from "types/api/region";
8	
9	export function useGeolocation(): UseGeolocationReturn {
10	  const t = useTranslations("Components.FiltersModal.geo");
11	  const [location, setLocation] = useState<GeolocationCoordinates | null>(null);
12	  const [isLoading, setIsLoading] = useState(false);
13	  const [error, setError] = useState<string | null>(null);
14	
15	  const requestLocation = useCallback(
16	    async (
17	      regions: RegionsGroupedByCitiesResponseDTO[]
18	    ): Promise<Option | null> => {
19	      if (!("geolocation" in navigator)) {
20	        setError(t("unsupported"));
21	        return null;
22	      }
23	
24	      setIsLoading(true);
25	      setError(null);
26	
27	      return new Promise((resolve) => {
28	        navigator.geolocation.getCurrentPosition(
29	          (position: GeolocationPosition) => {
30	            const coords = position.coords;
31	            setLocation(coords);
32	            setIsLoading(false);
33	
34	            // Find nearest city based on coordinates
35	            const nearestCity = findNearestCity(coords, regions);
36	            resolve(nearestCity);
37	          },
38	          (error: GeolocationPositionError) => {
39	            let errorMessage: string;
40	            switch (error.code) {
41	              case error.PERMISSION_DENIED:
42	                errorMessage = t("permissionDenied");
43	                break;
44	              case error.POSITION_UNAVAILABLE:
45	                errorMessage = t("positionUnavailable");
46	                break;
47	              case error.TIMEOUT:
48	                errorMessage = t("timeout");
49	                break;
50	              default:
51	                errorMessage = t("genericError");
52	            }
53	
54	            setError(errorMessage);
55	            setIsLoading(false);
56	            resolve(null);
57	          }
58	        );
59	      });
60	    },
61	    [t]
62	  );
63	
64	  const clearLocation = useCallback(() => {
65	    setLocation(null);
66	    setError(null);
67	  }, []);
68	
69	  return {
70	    location,
71	    isLoading,
72	    error,
73	    requestLocation,
74	    clearLocation,
75	  };
76	}
