8	function AvatarFallback({ name }: { name: string }) {
9	  const initial = name.charAt(0).toUpperCase();
10	  return (
11	    <div
12	      className="w-20 h-20 rounded-full bg-primary text-white flex items-center justify-center text-3xl font-bold"
13	      role="img"
