34	export default async function ProfileHeader({ profile }: ProfileHeaderProps) {
35	  const [t, locale] = await Promise.all([
36	    getTranslations("Components.Profile"),
37	    getLocaleSafely(),
38	  ]);
39	
40	  const joinedDateText = profile.createdAt
41	    ? formatJoinedDate(profile.createdAt, locale)
42	    : "";
43	
44	  // 2026-07-25 backend moved to `displayName`/`avatarUrl`. Legacy fields
45	  // come from older backend instances during the cut-over window.
46	  const displayName =
47	    profile.displayName?.trim() || profile.name?.trim() || profile.username;
48	  const avatarSrc = profile.avatarUrl || profile.pictureUrl;
49	
50	  // Cap runs of blank lines before rendering with whitespace-pre-line: the
51	  // 500-char limit alone doesn't stop a bio that's mostly newlines (e.g.
52	  // "\n" x200 plus a few words), which would otherwise blow up the page
53	  // with empty vertical space for every visitor. Normalize CRLF/CR to LF
54	  // first — otherwise a Windows-authored bio's "\r\n" runs slip past the
55	  // \n{3,} check entirely (the \r characters break up the consecutive-\n
56	  // count) and still produce the same wall of empty space.
57	  const bioText = profile.bio
58	    ?.trim()
59	    .replace(/\r\n?/g, "\n")
60	    .replace(/\n{3,}/g, "\n\n");
61	
62	  return (
63	    <section
64	      className="card-bordered rounded-lg overflow-hidden mb-section-y w-full"
65	      aria-label={t("title", { name: displayName })}
66	      data-testid="profile-header"
67	    >
68	      <div className="px-section-x py-element-gap relative">
69	        <div className="flex items-end gap-element-gap mb-element-gap">
70	          {avatarSrc ? (
71	            // bg-background: a transparent-background upload (e.g. a logo)
72	            // should show against a neutral backdrop, not whatever's behind it.
73	            <img
74	              src={avatarSrc}
75	              alt={displayName}
76	              className="w-20 h-20 rounded-full object-cover bg-background border-4 border-background shadow-md"
77	              loading="eager"
78	            />
79	          ) : (
80	            <AvatarFallback name={displayName} />
81	          )}
82	        </div>
83	
84	        <div className="flex items-center gap-2 mb-2 flex-wrap">
85	          <h1 className="heading-1 text-foreground">{displayName}</h1>
86	          <ProfileOwnerActions username={profile.username} />
87	        </div>
88	
89	        <p className="body-small text-foreground/60 mb-1">@{profile.username}</p>
90	
91	        {bioText && (
92	          <p
93	            data-testid="profile-bio"
94	            className="body-normal text-foreground/80 mb-element-gap whitespace-pre-line break-words"
95	          >
96	            {bioText}
97	          </p>
98	        )}
99	
100	        {joinedDateText && (
101	          <p className="body-small text-foreground/50">
102	            {t("joinedDate", { date: joinedDateText })}
103	          </p>
104	        )}
105	      </div>
106	    </section>
107	  );
108	}
