3	import { useRef, useState } from "react";
4	import { useTranslations } from "next-intl";
5	import { useAuth } from "@components/hooks/useAuth";
6	import type { EditProfileAvatarProps } from "types/props";
7	
8	// Mirrors the caps enforced server-side in app/api/users/me/avatar/route.ts.
9	// Checking here is UX only (fail before the upload round-trip) — the route
10	// is the real gate.
11	const MAX_AVATAR_BYTES = 2 * 1024 * 1024;
12	const ALLOWED_AVATAR_TYPES = new Set([
13	  "image/jpeg",
14	  "image/png",
15	  "image/jpg",
16	  "image/webp",
17	]);
18	
19	function AvatarFallback({ name }: { name: string }) {
20	  const initial = (name.trim().charAt(0) || "?").toUpperCase();
21	  return (
22	    <div
23	      className="w-20 h-20 rounded-full bg-primary text-white flex items-center justify-center text-3xl font-bold"
24	      role="img"
25	      aria-label={name}
26	    >
27	      {initial}
28	    </div>
29	  );
30	}
