32	export default function EditProfileAvatar({
33	  className,
34	}: EditProfileAvatarProps) {
35	  const t = useTranslations("App.EditProfile.avatar");
36	  const { user, refetchUser } = useAuth();
37	  const fileInputRef = useRef<HTMLInputElement>(null);
38	  const [isUploading, setIsUploading] = useState(false);
39	  const [isRemoving, setIsRemoving] = useState(false);
40	  const [error, setError] = useState<string | null>(null);
41	
42	  const displayName = user?.name || user?.username || "";
43	  const avatarUrl = user?.avatarUrl;
44	  const busy = isUploading || isRemoving;
45	
46	  const handleSelectClick = () => {
47	    setError(null);
48	    fileInputRef.current?.click();
49	  };
50	
51	  const handleFileChange = async (
52	    event: React.ChangeEvent<HTMLInputElement>,
53	  ): Promise<void> => {
54	    const file = event.target.files?.[0];
55	    event.target.value = ""; // allow re-selecting the same file later
56	    if (!file) return;
57	
58	    setError(null);
59	
60	    if (!ALLOWED_AVATAR_TYPES.has(file.type)) {
61	      setError(t("errorUnsupported"));
62	      return;
63	    }
64	    if (file.size > MAX_AVATAR_BYTES) {
65	      setError(t("errorTooLarge"));
66	      return;
67	    }
68	
69	    setIsUploading(true);
70	    try {
71	      const formData = new FormData();
72	      formData.append("avatarFile", file);
73	      const response = await fetch("/api/users/me/avatar", {
74	        method: "POST",
75	        credentials: "include",
76	        body: formData,
77	      });
78	      if (!response.ok) {
79	        setError(t("errorUploadFailed"));
80	        return;
81	      }
82	      await refetchUser();
83	    } catch {
84	      setError(t("errorUploadFailed"));
85	    } finally {
86	      setIsUploading(false);
87	    }
88	  };
89	
90	  const handleRemove = async (): Promise<void> => {
91	    setError(null);
92	    setIsRemoving(true);
93	    try {
94	      const response = await fetch("/api/users/me/avatar", {
95	        method: "DELETE",
96	        credentials: "include",
97	      });
98	      if (!response.ok) {
99	        setError(t("errorRemoveFailed"));
100	        return;
101	      }
102	      await refetchUser();
103	    } catch {
104	      setError(t("errorRemoveFailed"));
105	    } finally {
106	      setIsRemoving(false);
107	    }
108	  };
109	
110	  return (
111	    <div className={`w-full ${className ?? ""}`}>
112	      <label className="form-label">{t("label")}</label>
113	      <div className="mt-2 flex items-center gap-element-gap">
114	        {avatarUrl ? (
115	          // bg-background: a transparent-background upload (e.g. a logo) should
116	          // show against a neutral backdrop, not whatever's behind it.
117	          // eslint-disable-next-line @next/next/no-img-element -- user-uploaded, not eligible for static optimization
118	          <img
119	            src={avatarUrl}
120	            alt={t("altPreview")}
121	            className="w-20 h-20 rounded-full object-cover bg-background"
122	          />
123	        ) : (
124	          <AvatarFallback name={displayName} />
125	        )}
126	        <div className="flex flex-col gap-2">
127	          <button
128	            type="button"
129	            className="btn-outline btn-sm"
130	            onClick={handleSelectClick}
131	            disabled={busy}
132	          >
133	            {isUploading ? t("uploading") : t("uploadButton")}
134	          </button>
135	          {avatarUrl && (
136	            <button
137	              type="button"
138	              className="btn-outline btn-sm"
139	              onClick={() => {
140	                void handleRemove();
141	              }}
142	              disabled={busy}
143	            >
144	              {isRemoving ? t("removing") : t("removeButton")}
145	            </button>
146	          )}
147	        </div>
148	        <input
149	          ref={fileInputRef}
150	          type="file"
151	          accept="image/png, image/jpeg, image/jpg, image/webp"
152	          className="hidden"
153	          onChange={(event) => {
154	            void handleFileChange(event);
155	          }}
156	        />
157	      </div>
158	      {error && (
159	        <p className="helper-text-error mt-2" role="alert">
160	          {error}
161	        </p>
162	      )}
163	    </div>
164	  );
165	}
