26	export default async function OfflinePage() {
27	  const locale = (await rootLocale()) as AppLocale;
28	  const t = await getTranslations({ locale, namespace: "App.Offline" });
29	  const prefix = locale === DEFAULT_LOCALE ? "" : `/${locale}`;
30	  const withLocale = (path: string) => {
31	    if (!path.startsWith("/")) return path;
32	    if (!prefix) return path;
33	    if (path === "/") return prefix || "/";
34	    if (path.startsWith(prefix)) return path;
35	    return `${prefix}${path}`;
36	  };
37	  const absolute = (path: string) =>
38	    path.startsWith("http") ? path : `${siteUrl}${withLocale(path)}`;
39	  const offlineSchema = {
40	    "@context": "https://schema.org",
41	    "@type": "WebPage",
42	    "@id": `${absolute("/offline")}#webpage`,
43	    url: absolute("/offline"),
44	    name: t("schemaName"),
45	    description: t("schemaDescription"),
46	    isPartOf: { "@id": `${siteUrl}#website` },
47	  };
48	  return (
49	    <>
50	      <JsonLdServer id="offline-webpage-schema" data={offlineSchema} />
51	      <div
52	        className="min-h-screen flex items-center justify-center bg-muted"
53	        data-testid="offline-page"
54	      >
55	        <div className="text-center">
56	          <h1
57	            className="text-4xl font-bold text-foreground-strong mb-4"
58	            data-testid="offline-title"
59	          >
60	            {t("heading")}
61	          </h1>
62	          <p className="text-lg text-foreground/80 mb-8">{t("description")}</p>
63	          <PressableAnchor
64	            href={withLocale("/")}
65	            className="btn-primary"
66	            data-testid="offline-home-link"
67	            variant="inline"
68	          >
69	            {t("homeLink")}
70	          </PressableAnchor>
71	          <br />
72	          <PressableAnchor
73	            href={withLocale("/barcelona")}
74	            className="btn-neutral mt-4 mr-2"
75	            variant="inline"
76	          >
77	            {t("barcelona")}
78	          </PressableAnchor>
79	          <PressableAnchor
80	            href={withLocale("/catalunya")}
81	            className="btn-neutral mt-4"
82	            variant="inline"
83	          >
84	            {t("catalunya")}
85	          </PressableAnchor>
86	        </div>
87	      </div>
88	    </>
