18	const normalize = (value: string) => value.trim().toLowerCase();
19	const formatOptionalPlace = (value?: string | null) =>
20	  value && value.trim().length > 0 ? formatPlaceName(value) : "";
21	const isDistinctLabel = (candidate: string, ...others: string[]): boolean => {
22	  if (!candidate) return false;
23	  const normalizedCandidate = normalize(candidate);
24	  return !others.some(
25	    (other) => other && normalize(other) === normalizedCandidate,
26	  );
