29	/**
30	 * Build a clean location string:
31	 * - Deduplicate comma-separated segments
32	 * - Append city/region if missing
33	 * - Optionally hide city/region when separate links are displayed
34	 */
35	export const buildDisplayLocation = ({
36	  location,
37	  cityName,
38	  regionName,
39	  hidePlaceSegments,
40	}: BuildDisplayLocationOptions): string => {
41	  const formattedCityName = formatOptionalPlace(cityName);
42	  const formattedRegionName = formatOptionalPlace(regionName);
43	
44	  const baseSegments = location
45	    .split(",")
46	    .map((segment) => segment.trim())
47	    .filter(Boolean);
48	
49	  const uniqueSegments = baseSegments.reduce<string[]>((acc, segment) => {
50	    const key = normalize(segment);
51	    if (!acc.some((existing) => normalize(existing) === key)) {
52	      acc.push(segment);
53	    }
54	    return acc;
55	  }, []);
56	
57	  if (
58	    formattedCityName &&
59	    !uniqueSegments.some(
60	      (segment) => normalize(segment) === normalize(formattedCityName),
61	    )
62	  ) {
63	    uniqueSegments.push(formattedCityName);
64	  }
65	
66	  if (
67	    formattedRegionName &&
68	    !uniqueSegments.some(
69	      (segment) => normalize(segment) === normalize(formattedRegionName),
70	    )
71	  ) {
72	    uniqueSegments.push(formattedRegionName);
73	  }
74	
75	  const displaySegments = hidePlaceSegments
76	    ? uniqueSegments.filter((segment) => {
77	        const normalized = normalize(segment);
78	        return (
79	          normalized !== normalize(formattedCityName || "") &&
80	          normalized !== normalize(formattedRegionName || "")
81	        );
82	      })
83	    : uniqueSegments;
84	
85	  if (displaySegments.length > 0) {
86	    return displaySegments.join(", ");
87	  }
88	
89	  return uniqueSegments[0] ?? location;
90	};
