97	}: EventLocationLabelOptions): EventLocationLabels => {
98	  const cityLabel = formatOptionalPlace(cityName);
99	  const regionLabel = formatOptionalPlace(regionName);
100	  const venueLabel = formatOptionalPlace(location);
101	
102	  const primaryLabel = cityLabel || regionLabel || venueLabel || "";
103	  const preferRegion = secondaryPreference === "region";
104	  const preferredSecondary = preferRegion ? regionLabel : venueLabel;
105	  const fallbackSecondary = preferRegion ? venueLabel : regionLabel;
106	
107	  let secondaryLabel = "";
108	  if (isDistinctLabel(preferredSecondary, primaryLabel)) {
109	    secondaryLabel = preferredSecondary;
110	  } else if (
111	    isDistinctLabel(fallbackSecondary, primaryLabel, preferredSecondary)
112	  ) {
113	    secondaryLabel = fallbackSecondary;
114	  }
115	
116	  return {
117	    cityLabel,
118	    regionLabel,
119	    venueLabel,
120	    primaryLabel,
121	    secondaryLabel,
122	  };
