160	export const buildEventListLocationLabels = ({
161	  cityName,
162	  regionName,
163	  location,
164	}: EventPlaceLabelOptions): EventListLocationLabels => {
165	  const cityLabel = formatOptionalPlace(cityName);
166	  const regionLabel = formatOptionalPlace(regionName);
167	  const locationLabel = formatOptionalPlace(location);
168	
169	  // Primary: location (if available), otherwise city, otherwise region
170	  // Secondary: city and region combined (if distinct from primary)
171	  let primaryLabel = "";
172	  const secondaryParts: string[] = [];
173	
174	  if (locationLabel) {
175	    // Location exists - use it as primary
176	    primaryLabel = locationLabel;
177	    // Add city and region to secondary if they're distinct from location
178	    if (cityLabel && isDistinctLabel(cityLabel, locationLabel)) {
179	      secondaryParts.push(cityLabel);
180	    }
181	    if (regionLabel && isDistinctLabel(regionLabel, locationLabel)) {
182	      secondaryParts.push(regionLabel);
183	    }
184	  } else if (cityLabel) {
185	    // No location, but city exists - use city as primary
186	    primaryLabel = cityLabel;
187	    // Add region to secondary if distinct from city
188	    if (regionLabel && isDistinctLabel(regionLabel, cityLabel)) {
189	      secondaryParts.push(regionLabel);
190	    }
191	  } else if (regionLabel) {
192	    // Only region exists
193	    primaryLabel = regionLabel;
194	  }
195	
196	  // Combine secondary parts with comma
197	  const secondaryLabel =
198	    secondaryParts.length > 0 ? secondaryParts.join(", ") : "";
199	
200	  return {
201	    cityLabel,
202	    regionLabel,
203	    locationLabel,
204	    primaryLabel,
205	    secondaryLabel,
206	  };
207	};
