219	  // Return early without making API calls
220	  if (place === "catalunya") {
221	    return { type: "region", label: "Catalunya" };
222	  }
223	
224	  try {
225	    const placeInfo = await fetchPlaceBySlug(place);
226	    if (placeInfo) {
