232	            ? "region"
233	            : placeInfo.type === "PROVINCE"
234	              ? "region"
235	              : "town";
236	
237	      // For cities, look up parent region from cached data for SEO breadcrumbs
238	      if (type === "town") {
239	        try {
240	          const regionsWithCities = await fetchRegionsWithCities();
241	          for (const region of regionsWithCities) {
242	            const city = region.cities.find((c) => c.value === place);
243	            if (city) {
244	              return {
