248	                regionSlug: region.slug,
249	              };
250	            }
251	          }
252	        } catch {
253	          // Region lookup failed, return without region info
254	        }
255	      }
256	
257	      return { type, label: formattedLabel };
258	    }
259	  } catch (error) {
260	    console.error("Error fetching place by slug:", error);
261	  }
262	
263	  try {
264	    const regionsWithCities = await fetchRegionsWithCities();
265	
266	    const region = regionsWithCities.find(
267	      (r) =>
268	        r.slug === place ||
269	        sanitizeLegacyApostrophe(r.name) === place,
270	    );
271	    if (region) {
272	      return { type: "region", label: formatPlaceName(region.name) };
273	    }
