297	export const getDistance = (
298	  location1: Location,
299	  location2: Location,
300	): number => {
301	  const R = 6371;
302	  const dLat = deg2rad(location2.lat - location1.lat);
303	  const dLon = deg2rad(location2.lng - location1.lng);
304	  const a =
305	    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
306	    Math.cos(deg2rad(location1.lat)) *
307	      Math.cos(deg2rad(location2.lat)) *
308	      Math.sin(dLon / 2) *
309	      Math.sin(dLon / 2);
310	  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
