34	// DELETE /api/events/[slug] - delete event by slug (requires auth cookie).
35	// The backend enforces the creator check; we fail fast if no session exists.
36	export async function DELETE(
37	  _request: Request,
38	  context: { params: Promise<{ slug: string }> }
39	) {
40	  try {
41	    const currentUser = await getCurrentUser();
42	    if (!currentUser) {
43	      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
44	    }
45	
46	    const { slug } = await context.params;
47	    const event = await fetchExternalEvent(slug);
48	    if (!event) {
49	      return NextResponse.json({ error: "Event not found" }, { status: 404 });
50	    }
51	
52	    // Fail fast if the session does not belong to the event creator. The
53	    // backend also enforces this, but checking here avoids issuing a mutation
54	    // for events the caller does not own.
55	    const isCreator =
56	      Boolean(currentUser.id) &&
57	      currentUser.id === event.owner?.id;
58	    if (!isCreator) {
59	      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
60	    }
61	
62	    await deleteEventById(event.id);
63	    // Clear in-memory cache so next GET doesn't serve stale data
64	    deleteEventDetailCache(slug);
65	    // Purge Next.js fetch Data Cache for the specific event and all event
66	    // lists so deleted events don't remain in cached listing pages.
67	    revalidateTag(eventTag(slug), { expire: 0 });
68	    revalidateTag(eventsTag, { expire: 0 });
69	    revalidateTag(eventsCategorizedTag, { expire: 0 });
70	    // Purge Next.js Data Cache for all locales of the event detail page.
71	    // Default locale (ca) has no prefix; non-default locales get a prefix path.
72	    try {
73	      for (const locale of SUPPORTED_LOCALES) {
74	        const prefix = locale === DEFAULT_LOCALE ? "" : `/${locale}`;
75	        revalidatePath(`${prefix}/e/${slug}`);
76	      }
77	    } catch {
78	      // revalidatePath is a no-op outside of a render context in some environments
79	    }
80	    return new NextResponse(null, { status: 204 });
81	  } catch (e) {
82	    return handleApiError(e, "/api/events/[slug] DELETE");
83	  }
84	}
