450	    canPromptInstall || showIosInstructions || showOpenInSafariHint;
451	  const headlineText = canInstall ? t("installHeadline") : t("headline");
452	  const subtextText = canInstall ? t("installSubtext") : t("subtext");
453	
454	  /**
455	   * Close the popup.
456	   * @param countAsDismissal When false (post-success auto-close), the
457	   *   30-day cooldown still starts but the dismissal budget isn't burned.
458	   */
459	  const dismiss = useCallback(
460	    (countAsDismissal: boolean = true) => {
461	      // `counted: false` is a post-success auto-close, not a real decline —
462	      // keep both so decline rate = dismisses where counted is true.
463	      sendGoogleEvent("push_optin_dismiss", {
464	        source: "social_follow_popup",
465	        device: isMobileRef.current ? "mobile" : "desktop",
466	        install_state: installStateRef.current,
467	        counted: countAsDismissal,
468	      });
469	      // Cancel a pending post-success auto-close so a manual dismissal
470	      // doesn't trigger a second close cycle after the timer fires.
471	      if (autoCloseTimerRef.current) {
472	        clearTimeout(autoCloseTimerRef.current);
473	        autoCloseTimerRef.current = null;
474	      }
475	    setIsClosing(true);
476	    setTimeout(() => {
477	      setIsVisible(false);
478	      setIsClosing(false);
479	
480	      const current = getPopupState();
481	      savePopupState({
482	        dismissCount: (current?.dismissCount ?? 0) + (countAsDismissal ? 1 : 0),
483	        lastDismissedAt: Date.now(),
484	      });
485	    }, 300);
486	  }, []);
487	
488	  const handleSubscribePush = useCallback(async () => {
489	    sendGoogleEvent("push_optin_click", {
490	      source: "social_follow_popup",
491	      device: isMobile ? "mobile" : "desktop",
492	    });
493	    setIsSubscribingPush(true);
494	    try {
495	      const ok = await subscribeToPush();
496	      if (ok) {
497	        sendGoogleEvent("push_optin_success", {
498	          source: "social_follow_popup",
499	          device: isMobile ? "mobile" : "desktop",
500	        });
501	        // Goal reached: show the success state briefly, then close without
502	        // burning a dismissal (closing after success isn't a rejection).
503	        autoCloseTimerRef.current = setTimeout(
504	          () => dismiss(false),
505	          SUCCESS_AUTO_CLOSE_MS,
506	        );
507	      } else {
508	        sendGoogleEvent("push_optin_failed", {
509	          source: "social_follow_popup",
510	          device: isMobile ? "mobile" : "desktop",
511	          permission:
512	            typeof Notification !== "undefined"
513	              ? Notification.permission
514	              : "unsupported",
515	        });
516	      }
517	    } finally {
518	      setIsSubscribingPush(false);
519	    }
520	  }, [subscribeToPush, isMobile, dismiss]);
521	
522	  const handleInstall = useCallback(async () => {
523	    if (!canPromptInstall) return;
524	    sendGoogleEvent("pwa_install_click", {
525	      source: "social_follow_popup",
526	      device: isMobile ? "mobile" : "desktop",
527	    });
528	
529	    setIsInstalling(true);
530	    try {
531	      const outcome = await promptInstall();
532	      sendGoogleEvent("pwa_install_result", {
533	        source: "social_follow_popup",
534	        device: isMobile ? "mobile" : "desktop",
535	        outcome,
536	      });
537	      // Stay open on "accepted": the install section disappears and the
538	      // push CTA takes its place — the second step of the funnel.
539	    } finally {
540	      setIsInstalling(false);
541	    }
542	  }, [canPromptInstall, isMobile, promptInstall]);
543	
544	  // Clear any pending auto-close timer on unmount
545	  useEffect(() => {
546	    return () => {
547	      if (autoCloseTimerRef.current) clearTimeout(autoCloseTimerRef.current);
548	    };
549	  }, []);
550	
551	  // Escape key + focus trap for desktop modal (WAI-ARIA dialog pattern),
552	  // plus body scroll lock and focus restore.
553	  useEffect(() => {
554	    if (!isVisible) return;
555	
556	    const handleKeyDown = (e: KeyboardEvent) => {
557	      if (e.key === "Escape") {
558	        dismiss();
559	        return;
560	      }
561	
562	      // Focus trap only applies to desktop modal
563	      if (e.key !== "Tab" || isMobile) return;
564	      const dialog = dialogRef.current;
565	      if (!dialog) return;
566	
567	      const focusable = dialog.querySelectorAll<HTMLElement>(
568	        'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])',
569	      );
570	      if (focusable.length === 0) return;
571	
572	      const first = focusable[0];
573	      const last = focusable[focusable.length - 1];
574	
575	      if (e.shiftKey && document.activeElement === first) {
576	        e.preventDefault();
577	        last.focus();
578	      } else if (!e.shiftKey && document.activeElement === last) {
579	        e.preventDefault();
580	        first.focus();
581	      }
582	    };
583	
584	    let didLock = false;
585	    let previousBodyOverflow: string | null = null;
586	    if (!isMobile) {
587	      // Remember the focused element, move focus into the dialog, and lock
588	      // background scroll while the modal is open (desktop only — the
589	      // mobile toast is intentionally nonmodal).
590	      previousFocusRef.current =
591	        document.activeElement instanceof HTMLElement
592	          ? document.activeElement
593	          : null;
594	      const firstFocusable = dialogRef.current?.querySelector<HTMLElement>(
595	        'a[href], button:not([disabled])',
596	      );
597	      firstFocusable?.focus();
598	
599	      previousBodyOverflow = document.body.style.overflow;
600	      document.body.style.overflow = "hidden";
601	      didLock = true;
602	    }
603	
604	    document.addEventListener("keydown", handleKeyDown);
605	    return () => {
606	      document.removeEventListener("keydown", handleKeyDown);
